    // ---- the library ----
    private static final Linker LINKER = Linker.nativeLinker();
    private static final ConcurrentHashMap<String, MethodHandle> HANDLES = new ConcurrentHashMap<>();
    private static SymbolLookup lookup;

    /** Loads the engine library (a path, or null for the platform default name) and checks its ABI version. */
    public static synchronized void load(Path path) throws Throwable {
        Arena arena = Arena.global();
        String name = System.getProperty("os.name", "").toLowerCase().contains("win") ? "sturdy.dll"
                : System.getProperty("os.name", "").toLowerCase().contains("mac") ? "libsturdy.dylib" : "libsturdy.so";
        String environment = System.getenv("STURDY_LIBRARY");
        lookup = path != null ? SymbolLookup.libraryLookup(path, arena)
                : environment != null ? SymbolLookup.libraryLookup(Path.of(environment), arena) : SymbolLookup.libraryLookup(name, arena);
        int major = sturdy_abi_version_major();
        int minor = sturdy_abi_version_minor();
        if (major != ABI_MAJOR || minor < ABI_MINOR) {
            throw new IllegalStateException("the library implements ABI " + major + "." + minor + "; this binding needs " + ABI_MAJOR + "." + ABI_MINOR + " or a later minor");
        }
    }

    private static MethodHandle handle(String name, FunctionDescriptor descriptor) {
        return HANDLES.computeIfAbsent(name, n -> LINKER.downcallHandle(
                lookup.find(n).orElseThrow(() -> new UnsatisfiedLinkError(n + " is not exported by the loaded library")), descriptor));
    }

    // ---- functions ----

    // Major component of the ABI version this library implements.
    public static int sturdy_abi_version_major() throws Throwable {
        MethodHandle h = handle("sturdy_abi_version_major", FunctionDescriptor.of(ValueLayout.JAVA_INT));
        return (int) h.invokeExact();
    }

    // Minor component of the ABI version this library implements.
    public static int sturdy_abi_version_minor() throws Throwable {
        MethodHandle h = handle("sturdy_abi_version_minor", FunctionDescriptor.of(ValueLayout.JAVA_INT));
        return (int) h.invokeExact();
    }

